import { murmur2 } from './murmur2'; // Java-compatible, seed 0x9747b28c

export function partitionFor(key: string, n: number): number {
  const bytes = Buffer.from(key, 'utf8');
  return Math.abs(murmur2(bytes)) % n;
}

